                x, y = stack.pop()
                comp.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and
                        (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            if len(comp) == 1:
                singletons.append(comp[0])

    for r, c in singletons:
        counts = Counter()
        for rad in (1, 2, 3):
            counts.clear()
            for x in range(max(0, r-rad), min(h, r+rad+1)):
                for y in range(max(0, c-rad), min(w, c+rad+1)):
                    if (x, y) != (r, c):
                        counts[grid[x][y]] += 1
            counts.pop(grid[r][c], None)
            if counts:
                best = max(counts.values())
                tied = [v for v, n in counts.items() if n == best]
                out[r][c] = tied[0]
                break
    return out
